  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Fiecare se conectează la acest profil de pe dispozitivul sau managerul de parole care îl păstrează. Atinge unul pentru a-l redenumi sau elimina.',
