  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Pentru acest dispozitiv, o cheie de securitate, un manager de parole sau telefonul prin codul QR al browserului. Confirmă mai întâi că ești tu.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Nu se mai poate conecta la acest profil. Un dispozitiv deja conectat cu el rămâne conectat. Dacă l-ai pierdut, folosește Deconectează-te peste tot.',
