  'That code is wrong, already used or expired. Make a new one on your other device.': 'Codul este greșit, a fost deja folosit sau a expirat. Fă unul nou pe celălalt dispozitiv.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Acest browser nu poate confirma cu passkey-ul tău. Fă asta pe un dispozitiv care are unul.',
  'First confirm that it is you.': 'Confirmă mai întâi că ești tu.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Acest profil nu are passkey, iar serverul nu acceptă parole, așa că nimic nu poate confirma că ești tu. Întreabă administratorul.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Acest browser nu poate crea passkey-uri, așa că nu poate fi adăugat cu un cod. Deschide linkul într-un browser care poate.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Acest browser este conectat ca „{0}”. Adăugarea lui la „{1}” îl deconectează pe „{0}” aici.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Acest cod este pentru alt profil, care se numește și el „{0}”, nu pentru cel cu care este conectat acest browser. Adăugarea lui acolo te deconectează aici.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Continuă doar dacă acest cod vine de la un dispozitiv al tău. Acest browser se conectează atunci la “{0}”, iar ce înregistrezi aici merge în acel profil.',
