  'The next regular target continues from the last included workout.': 'Următoarea țintă obișnuită continuă de la ultimul antrenament inclus.',
  'Deload routine': 'Rutină de deload',
  'Its workouts do not count toward progression. They still show in history and statistics.': 'Antrenamentele lui nu contează pentru progresie. Apar totuși în istoric și statistici.',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'O rutină de deload pornește de la valorile setate aici, așa că progresia de mai sus nu se aplică.',
  'Linear progression': 'Progresie liniară',
