  'Add time': 'Adaugă timp',
  'Targets stay where you set them.': 'Țintele rămân acolo unde le stabilești.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Dacă faci fiecare repetare din fiecare serie, greutatea crește. Ratările repetate declanșează un deload.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Două serii normale plus o serie finală dusă până la eșec. Dacă bați ținta în seria aceea, greutatea crește (de două ori mai mult dacă dublezi repetările). Un eșec resetează 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Urci prin intervalul de repetări la aceeași greutate. Ajungi în vârful intervalului în fiecare serie, greutatea crește și repetările revin la baza intervalului.',
  'Hold every set for the full duration and the target goes up.': 'Menține fiecare serie toată durata și ținta crește.',
  'Nothing logged yet, so this session sets the baseline.': 'Încă nimic înregistrat, așa că această ședință stabilește referința.',
  'Held every set for the full time. Target goes up by {0}s.': 'Ai ținut fiecare serie tot timpul. Ținta crește cu {0}s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} sesiuni scurte la rând. Redu la {1} secunde și crește din nou.',
  'Came up short last time. Same target again.': 'Ai rămas sub țintă data trecută. Aceeași țintă din nou.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Vârful intervalului de repetări în fiecare serie. {0} {1} mai mult, înapoi la {2} repetări.',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'Blocat de {0} sesiuni. Deload la {1} {2}.',
  'Same weight, aim for {0} reps this time.': 'Aceeași greutate, țintește {0} repetări de data asta.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'Ultima serie a atins {0} repetări, dublu față de țintă! Fă un salt dublu de {1} {2}.',
  'Every rep last time. {0} {1} more.': 'Toate repetările data trecută. Cu {0} {1} mai mult.',
  'Every rep last time. {0} {1} less help.': 'Toate repetările data trecută. Cu {0} {1} mai puțin ajutor.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Vârful intervalului de repetări în fiecare serie. Cu {0} {1} mai puțin ajutor, înapoi la {2} repetări.',
  'Missed reps. {0} {1} of help while you build back up.': 'Repetări ratate. {0} {1} de ajutor până îți revii.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': 'Blocat de {0} sesiuni. Revino la {1} {2} de ajutor, apoi crește din nou.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'Repetări ratate {0} ședințe la rând. Resetează la {1} {2} și urcă din nou.',
  'Missed reps. Reset to {0} {1} and work back up.': 'Repetări ratate. Resetează la {0} {1} și urcă din nou.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'Ai ratat repetări ultima dată. Aceeași greutate din nou ({0} din {1} rămase).',
  'Bodyweight: every rep last time, so go for {0} this time.': 'Greutate corporală: toate repetările data trecută, așa că țintește {0} acum.',
  'Bodyweight: same target again until every set is clean.': 'Greutate corporală: aceeași țintă până când fiecare serie e curată.',
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} serii aduc un {1} cu ele. Activează Efort pe serie din Setări pentru a-l vedea.',
  '{0} sets bring an {1} with them.': '{0} serii aduc un {1} cu ele.',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': 'Efort pe serie',
  'What are RIR and RPE?': 'Ce sunt RIR și RPE?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': 'Cât de grea a fost o serie, înregistrat lângă greutate și repetări. Două scale pentru aceeași apreciere, numărate de la capete opuse.',
  'How it felt': 'Cum s-a simțit',
  'Nothing left, went to failure': 'Nimic rămas, până la epuizare',
  'One more rep in the tank': 'Încă o repetare în rezervor',
  'Two more reps': 'Încă două repetări',
  'Three more reps': 'Încă trei repetări',
  'Easy, warm-up territory': 'Ușor, zonă de încălzire',
  'Maybe half a rep left': 'Poate jumătate de repetare rămasă',
  'How hard was that set?': 'Cât de grea a fost seria?',
  'Tap how many reps you had left, or type an exact {0}.': 'Atinge câte repetări îți mai rămâneau sau scrie un {0} exact.',
  'Exact {0}': 'Exact {0}',
  'Clear rating': 'Șterge evaluarea',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR numără repetările pe care le-ai lăsat în rezervor; RPE citește același efort pe o scară de 10 puncte, deci RPE ≈ 10 − RIR. Alege-l pe cel în care gândești deja.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'Rândul evidențiat este acolo unde ajung majoritatea seriilor de lucru. Seriile deja înregistrate își păstrează propria scală, iar altceva nu citește valoarea, așa că progresia și 1RM estimat nu sunt afectate.',
  'Effort': 'Efort',
  'how close to failure': 'cât de aproape de eșec',
