  'Every muscle group got at least one hard set in this period.': 'Fiecare grupă musculară a primit cel puțin o serie grea în această perioadă.',
  'No rated sets in this period.': 'Nicio serie evaluată în această perioadă.',
  'average effort': 'efort mediu',
  'at {0} {1} or harder': 'la {0} {1} sau mai greu',
