  'Week by week': 'Săptămână cu săptămână',
  'Where the sets land': 'Unde ajung seriile',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'Majoritatea seriilor de lucru stau aproape de epuizare, nu la ea. Jumătate la minim și jumătate la maxim tot dau o medie care pare sănătoasă.',
  'Average effort per workout': 'Efort mediu pe antrenament',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': 'Un punct mai plin înseamnă mai puțin rămas în rezervor. Aceeași greutate la un {0} mai mic e progres pe care linia singură nu îl arată.',
  'Bodyweight': 'Greutate corporală',
  'No weight to enter. Just log the reps.': 'Nu e greutate de introdus. Doar înregistrează repetările.',
  'Ask for a weight on every set.': 'Cere o greutate la fiecare serie.',
  'For dips or pull-ups with a belt. Progression then follows the weight.': 'Pentru flotări pe paralele sau tracțiuni cu centură. Progresia urmează apoi greutatea.',
  'For lunges, single-arm rows and the like.': 'Pentru fandări, ramat cu o mână și altele asemenea.',
  'Top of the range': 'Vârful intervalului',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': 'Repetările cresc cu una când fiecare serie a fost curată. Setează un plafon ca să adaugi serii în loc să crească repetările la nesfârșit.',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': 'Repetările urcă până la {0}, apoi se adaugă o serie și repetările o iau de la capăt. La {1} serii îți propune să crești greutatea.',
  'Added ({0})': 'Adăugat ({0})',
  '{0}/side': '{0}/parte',
  '{0} reps in every set! Add a set and go back to {1}.': '{0} repetări în fiecare serie! Adaugă o serie și revino la {1}.',
  '{0} sets of {1}. Time to add weight or try a harder variation.': '{0} serii de {1}. E timpul să adaugi greutate sau să încerci o variantă mai grea.',
  '{0} per side': '{0} pe fiecare parte',
