  'Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.': 'Local păstrează totul pe acest telefon. Conectarea sincronizează în schimb cu propriul server openGym. Poți schimba mai târziu în Setări.',
