  'Warm-up sets': 'Serii de încălzire',
  'Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.': 'Adăugate înainte de seriile de lucru și lăsate în afara volumului, recordurilor și progresiei. Fiecare închide jumătate din diferența până la greutatea de lucru, niciodată sub bară la un exercițiu cu halteră, și le poți schimba oricând în timpul ședinței.',
  'Ramp-up sets added before the work sets, so you do not have to add them by hand each session.': 'Serii de încălzire adăugate înaintea seriilor de lucru, ca să nu le mai adaugi manual la fiecare sesiune.',
