  'Rest-pause always trains as one warm-up set at this rep count, then one rest-pause work set. "Sets" isn’t used here.': 'La rest-pause se lucrează mereu cu o serie de încălzire la acest număr de repetări, apoi o serie de lucru rest-pause. „Serii” nu se folosește aici.',
