  'AI Coach': 'Antrenor AI',
  'API key': 'Cheie API',
  'Bring my own API key': 'Aduc propria cheie API',
  'Could not reach the provider: {0}': 'Nu am putut ajunge la furnizor: {0}',
  'Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.': 'Android blochează conexiunile http:// necriptate din aplicații, așa că acest telefon poate ajunge doar la un endpoint https://. Pune HTTPS în față (Tailscale sau un proxy invers), sau alege „Folosesc openGym găzduit de mine”: serverul tău poate ajunge singur la un model http:// din rețeaua lui.',
  'Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.': 'Fiecare cerere merge direct la {0} cu cheia ta. Nimeni altcineva nu o vede, iar tu plătești.',
  'Endpoint': 'Endpoint',
  'Enter your API key': 'Introdu cheia API',
  'Enter the endpoint URL': 'Introdu URL-ul endpointului',
  'There’s no routine to review yet. Build one with at least two exercises first.': 'Nu există încă o rutină de analizat. Construiește mai întâi una cu cel puțin două exerciții.',
  'How should the Coach run?': 'Cum să funcționeze antrenorul AI?',
  'List models': 'Listează modelele',
  'Model': 'Model',
  'Nothing to change right now: {0}': 'Nimic de schimbat acum: {0}',
  'Off. Choose how the Coach should run.': 'Oprit. Alege cum să ruleze Antrenorul AI.',
  'Pick a model': 'Alege un model',
  'Provider': 'Furnizor',
  'Runs on this phone with your own API key': 'Rulează pe acest telefon cu cheia ta API',
  'Runs on your openGym server': 'Rulează pe serverul tău openGym',
  'Save and use the Coach': 'Salvează și folosește Antrenorul AI',
  'The Coach is already thinking about your training.': 'Antrenorul AI se gândește deja la antrenamentul tău.',
  'The Coach is taking a breather. You’ve used today’s {0} runs on this phone.': 'Antrenorul AI își trage sufletul. Ai folosit toate cele {0} încercări de azi pe acest telefon.',
  'The Coach isn’t set up on this phone.': 'Antrenorul AI nu este configurat pe acest telefon.',
  'The Coach needs your go-ahead first.': 'Antrenorul AI are nevoie mai întâi de acordul tău.',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'Cheia este păstrată în spațiul securizat al telefonului și nu pleacă de acolo decât ca să apeleze furnizorul.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'Acest telefon apelează direct furnizorul cu cheia ta. Fiecare cerere este taxată pe contul tău.',
  'Turn the Coach off on this phone': 'Oprește Antrenorul AI pe acest telefon',
  'Use my self-hosted openGym': 'Folosește openGym găzduit de mine',
  'What leaves this phone': 'Ce pleacă din acest telefon',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'Serverul tău nu are Antrenorul AI activat. Întreabă administratorul sau folosește propria cheie mai jos.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'Serverul tău rulează Antrenorul AI cu furnizorul configurat de administratorul său. Nimic nou nu pleacă de pe acest telefon în afara a ceea ce se sincronizează deja.',
  'Loading the exercise catalogue…': 'Se încarcă catalogul de exerciții…',
  'Checking the endpoint…': 'Se verifică endpointul…',
  'A local model can take longer.': 'Un model local poate dura mai mult.',
  'All optional. The more the Coach knows, the less it guesses.': 'Toate opționale. Cu cât Antrenorul AI știe mai mult, cu atât ghicește mai puțin.',
  'Almost there': 'Aproape gata',
  'Avoid: {0}': 'Evită: {0}',
  'Before we start': 'Înainte să începem',
  'Building your plan…': 'Se construiește planul…',
  'Discarded. Tell me what was off and I will build a different one.': 'Am renunțat. Spune-mi ce nu a fost în regulă și îți construiesc altul.',
  'Done! Your plan is back to how it was before my last changes.': 'Gata! Planul tău a revenit la starea de dinaintea ultimelor mele modificări.',
  'Edit my answers': 'Editează răspunsurile mele',
  'Start a new plan': 'Începe un plan nou',
  'A fresh plan from your answers; your workouts stay': 'Un plan nou din răspunsurile tale; antrenamentele tale rămân',
  'Build me a fresh plan from my answers.': 'Fă-mi un plan nou din răspunsurile mele.',
  'Experience': 'Experiență',
  'Goal, days, equipment, limits': 'Obiectiv, zile, echipament, limite',
  'Have a look at my training and tell me what you would change.': 'Aruncă o privire la antrenamentul meu și spune-mi ce ai schimba.',
  'Here is what I am working with:': 'Iată cu ce lucrez:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Salut, sunt antrenorul tău AI. Îți construiesc planul din răspunsurile tale și îl ajustez după ce înregistrezi efectiv. Nimic nu se schimbă până nu spui tu.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Am trecut prin tot și nu e nimic ce aș schimba acum. Ține-o tot așa și întreabă-mă din nou după câteva sesiuni.',
  'I understand, let’s go': 'Am înțeles, să mergem',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'Importat! {0} rutine sunt în planul tău și săptămâna e stabilită. Ne vedem la următoarea sesiune.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'Importat! {0} rutine sunt în planul tău. Săptămâna a rămas neschimbată; programează-le când vrei.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Îți concepe planul din câteva răspunsuri și îl ajustează după ce înregistrezi efectiv. Nu schimbă niciodată nimic fără acordul tău și poți anula fiecare modificare.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Rutine, exerciții, serii și repetări, orarul săptămânal și setările de progresie.',
  'Your logged training': 'Antrenamentele tale înregistrate',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'Seriile înregistrate în fereastra de analiză: greutăți, repetări, timpi, evaluări ale efortului, cât au durat sesiunile și notițele tale.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Cântăriri din aceeași perioadă, plus greutatea țintă dacă ai stabilit una.',
  'What you tell the Coach': 'Ce îi spui Antrenorului AI',
  'Your intake answers, including any limitations or injuries you describe.': 'Răspunsurile tale din chestionar, inclusiv orice limitări sau accidentări descrise.',
  'A few preferences': 'Câteva preferințe',
  'Your unit, your language and which effort scale you log.': 'Unitatea, limba și scara de efort pe care o folosești.',
