  'Sync now': 'Sincronizează acum',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Modificările tale sunt păstrate aici și vor fi fuzionate în contul tău când acesta este din nou împerecheat.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Modificările tale sunt păstrate aici și vor fi fuzionate în contul tău când te conectezi din nou.',
  'Changes kept for {0}': 'Modificări păstrate pentru {0}',
  'Added back when this device connects as that account again.': 'Se adaugă înapoi când acest dispozitiv se conectează din nou la acel cont.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Modificările pe care serverul nu le-a văzut rămân pe acest dispozitiv și sunt adăugate înapoi când se conectează din nou cu acest cont.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Acest telefon revine la modul doar local, iar copia contului tău este ștearsă. Mai întâi verifică dacă serverul are fiecare modificare. Dacă nu, tu alegi ce se întâmplă cu ele.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Datele tale sunt eliminate din acest browser; profilul tău de pe server le păstrează. Mai întâi se verifică dacă serverul are toate modificările. Dacă nu, alegi tu ce se întâmplă cu ele.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Deconectează acest profil de pe toate dispozitivele, inclusiv de pe acesta. Telefoanele asociate sunt deconectate și trebuie asociate din nou. Passkey-urile tale funcționează în continuare, așa că te poți conecta cu ele oricând.',
  '{0} change': '{0} modificare',
  '{0} changes': '{0} modificări',
  'Default progression': 'Progresie implicită',
  'Planned sessions start from': 'Ședințele planificate pornesc de la',
  'The routine’s sets and reps. Your history decides the weight.': 'Seriile și repetările rutinei. Istoricul tău decide greutatea.',
  'Your last session': 'Ultima ta sesiune',
  'The reps you logged last time in that routine, carried over, and any warm-ups you set up yourself. With progression off, the weight too.': 'Repetările pe care le-ai înregistrat ultima dată în acea rutină, preluate, plus încălzirile pe care le-ai stabilit singur. Cu progresia oprită, și greutatea.',
  'Last time means': 'Ultima dată înseamnă',
  'This routine': 'Această rutină',
  'Your last session of the exercise in the same routine. Heavy day and light day stay apart.': 'Ultima ta sesiune cu exercițiul din aceeași rutină. Ziua grea și ziua ușoară rămân separate.',
  'Any workout': 'Orice antrenament',
  'The last time you did the exercise, whichever routine it was in.': 'Ultima dată când ai făcut exercițiul, indiferent în ce rutină era.',
  'Plan changed, so starting from your new target.': 'Planul s-a schimbat, așa că pornim de la noua ta țintă.',
  'First time in this routine, so starting from its own target.': 'Prima dată în această rutină, așa că pornim de la ținta ei.',
  'No weight logged last time. Enter what you lift and progression takes it from there.': 'Nicio greutate înregistrată ultima dată. Introdu ce ridici, iar progresia pornește de acolo.',
