  'Edit workout': 'Editează antrenamentul',
  'Workout updated': 'Antrenament actualizat',
  'Save workout changes?': 'Salvezi modificările antrenamentului?',
  'Save your edits to this workout, or keep the original record.': 'Salvează modificările acestui antrenament sau păstrează înregistrarea originală.',
  'Save changes': 'Salvează modificările',
  'Don\'t save': 'Nu salva',
  'Keep editing': 'Continuă editarea',
  'This workout was deleted on another device. Your edits are still here.': 'Acest antrenament a fost șters de pe alt dispozitiv. Modificările tale sunt încă aici.',
  'Close editor': 'Închide editorul',
  'Editing a saved workout. Date and duration stay unchanged.': 'Editezi un antrenament salvat. Data și durata rămân neschimbate.',
  'A pull for every press, so the shoulders stay balanced.': 'O tragere pentru fiecare împingere, ca umerii să rămână echilibrați.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'O rotație de două zile pe trei ședințe pe săptămână, construită în jurul echipamentului pe care l-ai listat. Întâi exercițiile compuse, o tragere pentru fiecare împingere și destulă suprapunere între zile încât nimic să nu stea două săptămâni fără să fie antrenat.',
  'Based on the training already in this demo profile.': 'Pe baza antrenamentelor deja din acest profil demo.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Greutatea corporală a stagnat patru săptămâni, iar obiectivul e să crești. E o problemă de bucătărie, nu de antrenament. Planul nu e ce te ține pe loc.',
  'Demo': 'Demo',
  'Demo data reset': 'Resetare date demo',
  'Direct arm work, since you asked for it.': 'Lucru direct pentru brațe, fiindcă ai cerut.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Fiecare serie principală la acest exercițiu a fost la RPE 9,5 sau mai sus timp de trei sesiuni, iar greutatea nu s-a mișcat. Schimbarea mișcării pentru patru săptămâni deblochează de obicei mai repede decât să insiști pe aceeași.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Date exemplu, stocate doar în acest browser. Fă ce vrei și schimbă orice.',
  'Full body A': 'Tot corpul A',
  'Full body B': 'Tot corpul B',
  'Horizontal pressing, the other half of the session.': 'Împins orizontal, cealaltă jumătate a sesiunii.',
  'Live demo. Everything stays in this browser.': 'Demo live. Totul rămâne în acest browser.',
  'No training history yet, so starting conservatively.': 'Încă nu e istoric de antrenament, așa că pornim prudent.',
  'Passkey sign-in, sync across your devices, your own data.': 'Conectare cu passkey, sincronizare între dispozitivele tale, datele tale.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Readuce planul de exemplu, antrenamentele și cântăririle la starea inițială.',
  'Reset': 'Resetează',
  'Reset demo data': 'Resetează datele demo',
  'Reset demo data?': 'Resetezi datele demo?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Revizuit cum ai cerut. Tot ce nu ai contestat a rămas exact cum era.',
  'Same pattern, higher reps than day A.': 'Același tipar, mai multe repetări decât în ziua A.',
  'Self-host it in a minute →': 'Găzduiește-l singur într-un minut →',
  'Self-host openGym': 'Găzduiește-ți singur openGym',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Sesiunile se lungesc deja cu vreo cincisprezece minute. Acesta e exercițiul auxiliar care are cel mai puțin de pierdut dacă faci o serie mai puțin.',
  'Start the demo': 'Începe demonstrația',
  'The main lower-body driver, where most of the strength comes from.': 'Motorul principal al părții de jos, de unde vine cea mai mare parte a forței.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Aceleași tipare, variații diferite: destul numitor comun ca să progresezi, destulă diferență ca să rămâi proaspăt.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Mai întâi cele două tipare mari, de partea de jos și de împins, cât timp ești proaspăt.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Acest demo rulează în întregime în browserul tău, pe date de exemplu. Nimic nu este trimis nicăieri. Conectarea cu passkey și sincronizarea între dispozitive vin cu serverul openGym, pe care îl obții găzduindu-l singur.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Trei lucruri care merită schimbate și unul care merită știut. Restul merge: genuflexiunea și tracțiunile progresează amândouă conform planului.',
  'Vertical pressing.': 'Împins pe verticală.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Ai mutat această sesiune sâmbăta trei săptămâni la rând. Mai bine ar fi ca planul să spună asta, decât să tot treci peste el.',
