  'Server address unknown': 'Adresa serverului necunoscută',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Împerechează din nou sau exportă întâi un backup. Dacă mergi mai departe, o copie a acestor modificări rămâne pe acest dispozitiv până când se conectează din nou la acest server cu acest cont. Apoi sunt adăugate înapoi.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Conectează-te din nou sau exportă mai întâi un backup. Dacă mergi mai departe, o copie a acestor modificări rămâne pe acest dispozitiv până când se conectează din nou la acest server cu acest cont. Apoi sunt adăugate înapoi.',
