  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym nu mai poate scrie în folderul ales, așa că backupurile merg din nou în Documents/openGym. Alege din nou folderul pentru a reveni.',
  'Nudge me when I skip a planned workout': 'Amintește-mi când sar un antrenament planificat',
