  'Drill sergeant': 'Sergent instructor',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Un memento seara, într-o zi planificată fără nimic înregistrat, între 20:00 și 21:30. După 3 zile ratate la rând, tace până la următorul antrenament.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'Ai înregistrat un antrenament pe alt dispozitiv? Înainte să plece memento-ul, telefonul întreabă serverul ori de câte ori lasă aplicația să ruleze în fundal. Deschiderea aplicației recuperează mereu.',
  'Everything okay?': 'Totul în regulă?',
