  'No {0} today? Even a short session tomorrow counts.': 'Azi nu e {0}? Chiar și o ședință scurtă mâine contează.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Zi grea? {0} poate aștepta. Mâine e un început nou.',
  'Hey, {0} didn’t happen today. All good?': 'Hei, {0} nu s-a întâmplat azi. Totul bine?',
