  'Plan the final set as an all-out one.': 'Planifică ultima serie ca una la maximum.',
  'Triple progression': 'Progresie triplă',
  'Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.': 'Repetările urcă până la capătul intervalului, apoi se adaugă o serie, până la numărul maxim de serii. Când toate sunt la maxim, greutatea crește și revii la seriile și repetările inițiale.',
