  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'Ești singurul administrator aici, iar alte profiluri încă folosesc acest server. Fă mai întâi pe altcineva administrator.',
  'Couldn’t delete the account. Nothing was removed.': 'Nu am putut șterge contul. Nu s-a șters nimic.',
  'Your account is gone. Thanks for every rep.': 'Contul tău a dispărut. Mulțumim pentru fiecare repetare.',
  'Confirm it’s you to delete your openGym account': 'Confirmă că ești tu ca să ștergi contul openGym',
  'Not confirmed on this phone. Nothing was deleted.': 'Neconfirmat pe acest telefon. Nu s-a șters nimic.',
  'This phone has no screen lock, so the name you typed is the only check.': 'Acest telefon nu are blocare de ecran, așa că numele pe care l-ai scris este singura verificare.',
  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'Telefonul verifică dacă ești tu (față, amprentă sau cod), apoi contul este șters.',
