  'Sharper animations aren’t available on this device yet. The built-in ones work everywhere.': 'Animațiile mai fine nu sunt încă disponibile pe acest dispozitiv. Cele incluse funcționează peste tot.',
  'Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.': 'Animațiile mai fine se descarcă o dată pentru fiecare figură. Până ajung, vezi animațiile incluse, așa că nimic nu rămâne gol.',
