  'Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.': 'Încălzirile sunt ușoare, așa că pot avea pauză mai mică sau deloc. Ultima primește totuși pauza completă înainte de prima serie de lucru.',
  'Add photos': 'Adaugă poze',
  'Each photo goes on the day it was taken.': 'Fiecare poză apare în ziua în care a fost făcută.',
  'No progress photos yet. Add one for today or any day before.': 'Încă nu sunt poze de progres. Adaugă una pentru azi sau pentru orice zi dinainte.',
