  '{0} photos know their day and go there. The others go on the day below.': '{0} poze își știu ziua și merg acolo. Celelalte merg în ziua de mai jos.',
  'Every progress photo, lined up by date, for any day. Plus a before/after slider.': 'Toate pozele de progres, aliniate după dată, pentru orice zi. Plus un slider înainte/după.',
