  'Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.': 'Aparatul e ocupat? Alege ce ai face în schimb, iar o schimbare în timpul antrenamentului ți le propune întâi pe acestea.',
  'Remove “{0}”': 'Elimină „{0}”',
