  'Nothing to add in weight here: it goes up in reps, then sets.': 'Nimic de adăugat la greutate aici: se crește în repetări, apoi în serii.',
  'In Cards and Focus, Prev and Next hop over a finished exercise.': 'În Carduri și Focus, Anterior și Următor sar peste un exercițiu terminat.',
  'Skip completed exercises': 'Sari peste exercițiile terminate',
  'This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.': 'Această aplicație nu poate confirma cu un passkey. Fă codul într-un browser conectat la acest profil sau adaugă mai întâi o parolă acolo.',
