  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'Nepermis pe ceas. Permite-l în aplicația Health de pe iPhone.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Ritmul cardiac în timpul antrenamentului și lângă fiecare serie, iar antrenamentul salvat în Apple Health. Ceasul cere o singură dată.',
