  'Write to Apple Health': 'Scrie în Apple Health',
  'Open Apple Health': 'Deschide Apple Health',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Antrenamentele și cântăririle ajung în Apple Health când le termini sau le modifici.',
