  'Your bar for this type, set in Your bars.': 'Bara ta pentru acest tip, setată în Barele tale.',
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'Cât cântărește bara din sala ta. Fiecare exercițiu cu acea bară numără discurile de la ea, dacă nu i-ai dat exercițiului propria bară. Greutățile înregistrate rămân totaluri.',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'Majoritatea exercițiilor din bibliotecă folosesc “{0}”, câteva folosesc “{1}”. O bară scurtă pentru toate înseamnă să le setezi pe amândouă.',
