  'Original': 'Original',
  'Mono': 'Mono',
  'Just for this phone. Some home screens take a moment to catch up.': 'Doar pentru acest telefon. Unele ecrane principale au nevoie de un moment să se actualizeze.',
  'New icon on its way. It shows up once you leave the app.': 'Pictograma nouă e pe drum. Apare după ce ieși din aplicație.',
  'The icon could not be changed.': 'Pictograma nu a putut fi schimbată.',
