  'Each adds its own routines, so your plan stays as it is until you start it.': 'Fiecare adaugă propriile rutine, așa că planul rămâne cum este până îl începi.',
  'Effort for the week': 'Efortul săptămânii',
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': 'Gol lasă greutatea în seama progresiei tale. Un %1RM se calculează din cel mai bun 1RM estimat.',
  'End programme': 'Încheie programul',
  'End “{0}”?': 'Închei „{0}”?',
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': 'Patru zile. Progresia ta alege greutățile, efortul urcă până la RPE 9, apoi un deload.',
  'Heavier means every %1RM goes up {0} points.': 'Mai greu înseamnă că fiecare %1RM crește cu {0} puncte.',
  'It is running: ending it brings your plan back. Its routines stay.': 'Rulează: dacă îl închei, planul tău revine. Rutinele lui rămân.',
  'Its routines stay.': 'Rutinele lui rămân.',
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': 'Programul lui preia planul tău până îl închei. Apoi planul tău revine cum era.',
  'Lighter weights, and its sessions do not count toward progression.': 'Greutăți mai mici, iar ședințele lui nu contează pentru progresie.',
  'Linear 5×5 style, 12 weeks': 'Stil liniar 5×5, 12 săptămâni',
