  'Pick one. Muscle groups are optional, but they feed the body map and muscle balance.': 'Alege unul. Grupele musculare sunt opționale, dar alimentează harta corpului și echilibrul mușchilor.',
  'Pick your exercises': 'Alege-ți exercițiile',
  'Practice copy gone': 'Copia de exersare a fost ștearsă',
  'Practice session': 'Sesiune de exersare',
  'Push Day, Legs, Monday Misery. Tap the name and type your own.': 'Zi de împins, Picioare, Luni groaznice. Apasă numele și scrie ce vrei.',
  'Reopens it: sets, weights, reps, exercises. Nothing changes until you tap Save.': 'Îl redeschide: serii, greutăți, repetări, exerciții. Nimic nu se schimbă până apeși Salvează.',
  'Restore a backup': 'Restaurează un backup',
  'Routine name': 'Numele rutinei',
  'Routines are made in Plan. Tap it.': 'Rutinele se creează în Plan. Apasă pe el.',
  'Save plan': 'Salvează planul',
  'Save your plan?': 'Salvezi planul?',
  'Saved!': 'Salvat!',
  'Search finds your exercises like any other, and they go into routines and workouts the same way.': 'Căutarea îți găsește exercițiile ca oricare altele, iar ele intră în rutine și antrenamente la fel.',
  'Settings are on Home': 'Setările sunt pe Acasă',
  'Share weigh-ins and workouts with the phone’s health app.': 'Partajează cântăririle și antrenamentele cu aplicația de sănătate a telefonului.',
  'So the equipment filter and your gym profiles know about it.': 'Ca filtrul de echipament și profilurile sălilor tale să știe despre asta.',
  'Spreadsheet': 'Foaie de calcul',
  'Strong, Hevy, FitNotes, GymMane or Apple Health body weight: import their export here.': 'Strong, Hevy, FitNotes, GymMane sau greutatea corporală din Apple Health: importă aici exportul lor.',
  'Syncing lives under your account. Tap back to Settings.': 'Sincronizarea se află în contul tău. Apasă înapoi la Setări.',
  'Syncing your devices through your own openGym server lives under your account. No server? Everything still works on this device.': 'Sincronizarea dispozitivelor prin propriul server openGym se află în contul tău. Fără server? Totul funcționează în continuare pe acest dispozitiv.',
  'Tap Add and pick your new routine. The loop runs in that order.': 'Apasă Adaugă și alege-ți noua rutină. Bucla rulează în ordinea aceea.',
  'Tap Add exercise to pick what goes in.': 'Apasă Adaugă exercițiu ca să alegi ce intră.',
  'Tap All weigh-ins.': 'Apasă Toate cântăririle.',
  'Tap Create exercise when it looks right. Or Next to just look around.': 'Apasă Creează exercițiu când arată bine. Sau Următorul dacă vrei doar să te uiți.',
  'Tap New routine. It stays a draft until you save it.': 'Apasă Rutină nouă. Rămâne o ciornă până o salvezi.',
  'Tap Schedule to put it on a day.': 'Apasă Orar ca să o pui într-o zi.',
  'Tap a weekday and choose your new routine. Two on one day works too.': 'Apasă pe o zi a săptămânii și alege-ți noua rutină. Merge și două într-o zi.',
  'Tap an exercise any time to change sets, reps or weight. The arrows reorder, the link makes a superset.': 'Apasă pe un exercițiu oricând ca să schimbi serii, repetări sau greutate. Săgețile reordonează, veriga face un superset.',
  'Tap back to Settings.': 'Apasă înapoi la Setări.',
  'Tap back.': 'Apasă înapoi.',
  'Tap it.': 'Atinge-l.',
  'Tap one to set its sets, reps and weight, or + to take the usual. Close the list when you’re done.': 'Atinge unul ca să îi stabilești seriile, repetările și greutatea, sau + ca să iei valorile obișnuite. Închide lista când ai terminat.',
  'That’s a plan': 'Acesta este un plan',
  'That’s the lot': 'Asta e tot',
  'The bin deletes one, and Undo pops up right after. Wrong number? Log that day again and the new one wins.': 'Coșul șterge o valoare, iar Anulează apare imediat. Ai greșit cifra? Înregistrează din nou ziua și cea nouă câștigă.',
  'The exercise library': 'Biblioteca de exerciții',
  'The gear': 'Echipamentul',
  'The phone saves a fresh backup by itself after changes.': 'Telefonul salvează singur un backup nou după modificări.',
  'They live under Stats. Tap it.': 'Sunt sub Statistici. Atinge-l.',
  'They’re on Home. Tap it.': 'Sunt pe Acasă. Atinge-l.',
  'This is your real plan now, if you want it. Save keeps it. Skip and it was never here.': 'Acesta este planul tău real acum, dacă îl vrei. Dacă apeși Salvează, rămâne. Dacă sari peste, nu a existat niciodată.',
  'This one is for real: we build a routine together and it lands in your plan when you tap Save. Bail before that and nothing stays behind.': 'Acesta este pe bune: construim o rutină împreună și ajunge în planul tău când apeși Salvează. Dacă renunți înainte, nu rămâne nimic.',
  'Tutorials': 'Tutoriale',
  'Up one level': 'Cu un nivel mai sus',
  'Want more? Each of these is a short guided run. You’ll find them again in Settings → About & updates.': 'Vrei mai mult? Fiecare dintre acestea este o rundă scurtă ghidată. Le găsești din nou în Setări → Despre și actualizări.',
  'We swapped in a practice copy with a pretend workout and weigh-in. Poke at anything, nothing here sticks.': 'Am pus o copie de exercițiu cu un antrenament și o cântărire imaginare. Încearcă orice, nimic nu rămâne aici.',
  'Weigh-ins first': 'Cântăririle primele',
  'Weight unit, plates and stack live here. Edit or delete the exercise from here too.': 'Unitatea de greutate, discurile și greutățile disponibile sunt aici. Editează sau șterge exercițiul tot de aici.',
  'What you can’t edit': 'Ce nu poți edita',
  'When do you train it?': 'Când te antrenezi pentru el?',
  'Where your data goes in and out. We only point, nothing runs until you tap it yourself.': 'Pe unde intră și ies datele tale. Doar arătăm, nimic nu rulează până nu apeși tu.',
  'Workouts, weigh-ins and what can be fixed': 'Antrenamente, cântăriri și ce poate fi reparat',
  'Your data, your call. Back it up now and then, future you will be grateful.': 'Datele tale, decizia ta. Fă un backup din când în când, viitorul tău îți va mulțumi.',
