  'This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.': 'Acesta este demo-ul, așa că nu există niciun model AI în spatele meu. Pe serverul tău îți citesc ședința și sugerez modificări ca acestea.',
